const response = $json;
const message = response.choices?.[0]?.message?.content ?? '';

return [
  {
    json: {
      data: {
        flow_type: 'review',
        status: 'completed',
        model_used: response.model ?? 'openai/gpt-4o-mini',
        review: message,
        provider_response_id: response.id ?? null
      },
      meta: {
        timestamp: new Date().toISOString()
      }
    }
  }
];
